DELETE
FROM "interviewworks_schema"."quotations" q
WHERE EXISTS (SELECT 1
              FROM "interviewworks_schema"."userdata_details" ud
              WHERE q.username = ud.username
                and ud.username = #{username}
                and q.quotation_id = #{quotation_id}
              )

mapper.update:
update "interviewworks_schema"."quotations"
set status = #{status}
where username = #{username}
  and quotation_id = #{quotation_id}
